  <!-- ========== HEADER ========== -->
  <header class="header" id="header">
    <a href="index.html" class="logo">StreamWave</a>
    <div class="header-right">
      <select class="lang-select" aria-label="Language">
        <option value="en">English</option>
      </select>
      <a href="login.html" class="btn-sign-in">Sign In</a>
    </div>
  </header>

  <!-- ========== HERO ========== -->
  <section class="hero" id="hero">
    <div class="hero-bg">
      <div class="hero-mosaic">
        <div class="mosaic-tile" style="background:linear-gradient(135deg,#2d1b4e,#1a0a2e)"></div>
        <div class="mosaic-tile" style="background:linear-gradient(135deg,#4a1c1c,#2a0a0a)"></div>
        <div class="mosaic-tile" style="background:linear-gradient(135deg,#1c3a4a,#0a1a2a)"></div>
        <div class="mosaic-tile" style="background:linear-gradient(135deg,#3a3a1c,#1a1a0a)"></div>
        <div class="mosaic-tile" style="background:linear-gradient(135deg,#1c4a2d,#0a2a1a)"></div>
        <div class="mosaic-tile" style="background:linear-gradient(135deg,#4a1c3a,#2a0a1a)"></div>
        <div class="mosaic-tile" style="background:linear-gradient(135deg,#1c2d4a,#0a1a2a)"></div>
        <div class="mosaic-tile" style="background:linear-gradient(135deg,#4a2d1c,#2a1a0a)"></div>
        <div class="mosaic-tile" style="background:linear-gradient(135deg,#2d4a1c,#1a2a0a)"></div>
