    helpBtn.addEventListener('click', () => {
      const isOpen = helpContent.classList.contains('open');
      helpContent.classList.toggle('open');
      helpBtn.classList.toggle('active');
      helpBtn.setAttribute('aria-expanded', !isOpen);
    });
